454	    /// The parameter `num_ops` is the approximate number of virtual machine
455	    /// instructions that are evaluated between successive invocations of the
456	    /// `handler`. If `num_ops` is less than one then the progress handler
457	    /// is disabled.
458	    ///
459	    /// If the progress callback returns `true`, the operation is interrupted.
460	    pub fn progress_handler<F>(&mut self, num_ops: c_int, handler: Option<F>) -> Result<()>
461	    where
462	        F: FnMut() -> bool + Send + 'static,
463	    {
464	        self.db.borrow_mut().progress_handler(num_ops, handler)
465	    }
