502	impl Wal {
503	    /// Checkpoint a database
504	    pub fn checkpoint(&self) -> Result<()> {
505	        unsafe { decode_result_raw(self.db, ffi::sqlite3_wal_checkpoint(self.db, self.db_name)) }
506	    }
507	
508	    /// Checkpoint a database
509	    pub fn checkpoint_v2(&self, mode: CheckpointMode) -> Result<(c_int, c_int)> {
510	        let mut n_log = 0;
511	        let mut n_ckpt = 0;
512	        unsafe {
513	            decode_result_raw(
514	                self.db,
515	                ffi::sqlite3_wal_checkpoint_v2(
516	                    self.db,
517	                    self.db_name,
518	                    mode as c_int,
519	                    &raw mut n_log,
520	                    &raw mut n_ckpt,
521	                ),
522	            )?;
523	        };
524	        Ok((n_log, n_ckpt))
525	    }
