599	impl InnerConnection {
600	    /// ```compile_fail
601	    /// use rusqlite::{Connection, Result};
602	    /// fn main() -> Result<()> {
603	    ///     let mut db = Connection::open_in_memory()?;
604	    ///     {
605	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
606	    ///         db.commit_hook(Some(|| {
607	    ///             called.store(true, std::sync::atomic::Ordering::Relaxed);
608	    ///             true
609	    ///         }));
610	    ///     }
611	    ///     assert!(db
612	    ///         .execute_batch(
613	    ///             "BEGIN;
614	    ///         CREATE TABLE foo (t TEXT);
615	    ///         COMMIT;",
616	    ///         )
617	    ///         .is_err());
