115	        let mut shared_handle = self.interrupt_lock.lock().unwrap();
116	        assert!(
117	            !self.owned || !shared_handle.is_null(),
118	            "Bug: Somehow interrupt_lock was cleared before the DB was closed"
119	        );
120	        if !self.owned {
121	            self.db = ptr::null_mut();
122	            return Ok(());
123	        }
124	        unsafe {
125	            let r = ffi::sqlite3_close(self.db);
126	            // Need to use _raw because _guard has a reference out, and
127	            // decode_result takes &mut self.
128	            let r = decode_result_raw(self.db, r);
129	            if r.is_ok() {
130	                *shared_handle = ptr::null_mut();
131	                self.db = ptr::null_mut();
