/// The wal hook registered on a connection.
struct WalHookState {
    hook: Box<dyn FnMut(&Wal, c_int) -> Result<()> + Send>,
    /// The reason the hook failed the most recent notification, to be
    /// reported by the database call that observes SQLite's generic
    /// `SQLITE_ERROR`. Reset on every hook invocation, so a stale reason can
    /// never be attributed to a later failure.
    error: Option<Error>,
}

unsafe extern "C" fn wal_hook_callback(
    client_data: *mut c_void,
    db: *mut ffi::sqlite3,
    db_name: *const c_char,
    pages: c_int,
) -> c_int {
    unsafe {
        let state: *mut WalHookState = client_data.cast();
        let wal = Wal { db, db_name };
        let r = catch_unwind(AssertUnwindSafe(|| ((*state).hook)(&wal, pages)));
        let (code, error) = match r {
            Ok(Ok(())) => (ffi::SQLITE_OK, None),
            Ok(Err(err)) => {
                // SQLite only forwards whether the hook failed, not the
                // reason: `sqlite3_step` reports a generic `SQLITE_ERROR`
                // whatever code is returned here. Keep the hook's own code
                // for the raw SQLite error state, but never report success.
                let code = err
                    .sqlite_error()
                    .map_or(ffi::SQLITE_ERROR, |x| x.extended_code);
                (
                    if code == ffi::SQLITE_OK {
                        ffi::SQLITE_ERROR
                    } else {
                        code
                    },
                    Some(err),
                )
            }
            Err(_) => (ffi::SQLITE_ERROR, Some(Error::UnwindingPanic)),
        };
        (*state).error = error;
        code
    }
}

/// If the wal hook on `db` failed during the database call now being
/// reported as failed, take and return the reason it provided. The reason
/// is consumed, so it is reported at most once, by the first call that
/// observes the failure; the committed write is not affected.
pub(crate) unsafe fn take_wal_hook_error(db: *mut ffi::sqlite3) -> Option<Error> {
    if db.is_null() {
        return None;
    }
    let state =
        unsafe { ffi::sqlite3_get_clientdata(db, c"sqlite3_wal_hook".as_ptr()) }.cast::<WalHookState>();
    if state.is_null() {
        return None;
    }
    unsafe { (*state).error.take() }
}
